import { useId } from "react";
import type { IconProps } from "./icon";

const steps = { xs: 12, sm: 16, md: 20, lg: 24, xl: 32 } as const;

export type SunMoonMode = "sun" | "moon" | "dawn";

export type SunMoonIconProps = Omit<IconProps, "title"> & {
  /** `true` draws the moon, `false` the sun. Changing it morphs one into the other. Ignored when `mode` is set. */
  moon?: boolean;
  /** `sun`, `moon`, or `dawn` (a half sun rising over a horizon). Changing it morphs between them. */
  mode?: SunMoonMode;
};

const RAYS = [
  "M12 2.8v2",
  "M12 19.2v2",
  "M2.8 12h2",
  "M19.2 12h2",
  "M5.5 5.5L6.9 6.9",
  "M17.1 17.1l1.4 1.4",
  "M18.5 5.5l-1.4 1.4",
  "M6.9 17.1l-1.4 1.4",
];

/**
 * A sun that becomes a moon. The rays shrink and turn while a second disc slides across the sun and carves a crescent;
 * it plays on every change of `moon` and holds still under reduced motion. Decorative: label the button around it.
 */
export function SunMoonIcon({
  moon = false,
  mode,
  size = "1em",
  strokeWidth = 1.75,
  className,
  ...rest
}: SunMoonIconProps) {
  const id = useId();
  const current: SunMoonMode = mode ?? (moon ? "moon" : "sun");
  const px = typeof size === "string" && size in steps ? steps[size as keyof typeof steps] : size;
  return (
    <svg
      viewBox="0 0 24 24"
      width={px}
      height={px}
      fill="none"
      stroke="currentColor"
      strokeWidth={strokeWidth}
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      focusable="false"
      className={className ? `hm-icon hm-sunmoon ${className}` : "hm-icon hm-sunmoon"}
      data-moon={current === "moon" ? "" : undefined}
      data-mode={current}
      {...rest}
    >
      <defs>
        <mask id={`${id}-m`}>
          <rect x="0" y="0" width="24" height="24" fill="white" />
          <circle className="hm-sunmoon-bite" cx="14.6" cy="9.4" r="5.2" fill="black" />
          <rect className="hm-sunmoon-sea" x="0" y="14" width="24" height="10" fill="black" />
        </mask>
        <clipPath id={`${id}-c`}>
          <circle cx="12" cy="12" r="5.2" />
        </clipPath>
      </defs>
      <g className="hm-sunmoon-body">
        <circle className="hm-sunmoon-disc" cx="12" cy="12" r="5.2" mask={`url(#${id}-m)`} />
        {/* the crescent's inner edge: the bite's outline, clipped to the sun's disc, so it only shows once it overlaps */}
        <g clipPath={`url(#${id}-c)`}>
          <circle className="hm-sunmoon-bite hm-sunmoon-edge" cx="14.6" cy="9.4" r="5.2" />
        </g>
        <g className="hm-sunmoon-rays">
          {RAYS.map((d) => (
            <path key={d} d={d} />
          ))}
        </g>
      </g>
      <path className="hm-sunmoon-horizon" d="M4.5 18.5h15" />
    </svg>
  );
}
